import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"لنگر سمبیوٹک تہذیب کا اعلامیہ","description":"","frontmatter":{},"headers":[],"relativePath":"ur/01-锚点共生文明宣言.md","filePath":"ur/01-锚点共生文明宣言.md"}'),o={name:"ur/01-锚点共生文明宣言.md"};function d(i,t,h,n,s,u){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="لنگر-سمبیوٹک-تہذیب-کا-اعلامیہ" tabindex="-1">لنگر سمبیوٹک تہذیب کا اعلامیہ <a class="header-anchor" href="#لنگر-سمبیوٹک-تہذیب-کا-اعلامیہ" aria-label="Permalink to &quot;لنگر سمبیوٹک تہذیب کا اعلامیہ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>01</td></tr><tr><td>ماڈیول</td><td>عمومی اصول اور بنیادی ترتیبات</td></tr><tr><td>کلیدی الفاظ</td><td>اعلامیہ، سمبیوسس، لوٹ مار مخالف، دس ہزار نسلیں، ارتقاء کا حق</td></tr></tbody></table><h2 id="اولًا-اعلامیے-کی-تاریخی-پس-منظر" tabindex="-1">اولًا. اعلامیے کی تاریخی پس منظر <a class="header-anchor" href="#اولًا-اعلامیے-کی-تاریخی-پس-منظر" aria-label="Permalink to &quot;اولًا. اعلامیے کی تاریخی پس منظر&quot;">​</a></h2><p>دس ہزار ارواح اور متوازن لنگر کی اصلی کائنات (مختصراً &quot;ہینگ یوانژو&quot;) کی طویل تاریخ میں، لوٹ مار والی سادھائی کا نظام طویل عرصے سے کائناتی ترتیب پر غالب تھا۔ طاقتور لوگ کمزوروں کی اصل، قسمت اور زندگی کی توانائی کو کھا کر اپنی ترقی کے سیڑھی کے طور پر استعمال کرتے تھے； فرقے سادھائی کے طریقوں کی اجارہ داری کو حکومت کی بنیاد کے طور پر استعمال کرتے تھے； اور جہتیں جنگ اور غلامی کو توسیع کے راستے کے طور پر اپناتی تھیں۔ اس نظام نے مختصر مدت میں چند اعلیٰ ترین طاقتور سادھکوں کو جنم دیا تھا، لیکن طویل مدت میں اس نے کائنات کی ارتقاء کی صلاحیت کو ختم کر دیا تھا، جس کے نتیجے میں تہذیبی وقفے بار بار واقع ہوتے، دس ہزار نسلیں زوال پذیر ہوتیں، اور کائناتی اینٹروپی میں تیزی سے اضافہ ہوتا۔</p><p>لنگر سمبیوٹک تہذیب کی پیدائش اس تاریخی بحران کا بنیادی جواب ہے۔ یہ اعلامیہ اعلان کرتا ہے: لوٹ مار والی سادھائی کے نظام کا دور ختم ہو چکا ہے، اور سمبیوٹک ارتقاء کا نیا دور شروع ہو چکا ہے۔ ہینگ یوانژو میں تمام زندگیاں، نسل، شکل یا سادھائی کی سطح سے قطع نظر، برابر ارتقاء کے حقوق سے لطف اندوز ہوتی ہیں۔</p><h2 id="ثانیًا-اعلامیے-کے-بنیادی-دعوے" tabindex="-1">ثانیًا. اعلامیے کے بنیادی دعوے <a class="header-anchor" href="#ثانیًا-اعلامیے-کے-بنیادی-دعوے" aria-label="Permalink to &quot;ثانیًا. اعلامیے کے بنیادی دعوے&quot;">​</a></h2><p>یہ اعلامیہ درج ذیل ناقابل تزلزل بنیادی دعوے قائم کرتا ہے:</p><ol><li><strong>ارتقاء کے حقوق کی برابری</strong>: ہر زندگی کو اپنا ارتقاء کا راستہ منتخب کرنے کا بنیادی حق ہے، اور کوئی بھی تنظیم یا فرد کسی بھی وجہ سے اس حق کو چھین یا محدود نہیں کر سکتا۔</li><li><strong>لوٹ مار مخالف اصول</strong>: دوسری زندگیوں کی اصل یا توانائی کو کھانے، غلامی یا استحصال کے ذریعے سادھائی کرنا ممنوع ہے؛ تمام ارتقاء کو سمبیوٹک چکر کی بنیاد پر قائم کیا جانا چاہیے۔</li><li><strong>نظام کی کھلے پن</strong>: تین سو اصلی سادھائی کے نظام دس ہزار نسلوں کے لیے مفت کھلے ہیں، اور سادھائی کے طریقے اب چند لوگوں کی نجی ملکیت نہیں ہیں۔</li><li><strong>زیادہ محنت، زیادہ انعام</strong>: ارتقاء کے نتائج انفرادی کوشش کے مطابق ہوتے ہیں؛ بغیر محنت کے لوٹ مار والی تقسیم کی مخالفت کی جاتی ہے، اور یکساںیت کے سست تقسیم کی بھی مخالفت کی جاتی ہے۔</li><li><strong>خود ساختہ نشوونما</strong>: ہر زندگی کی خود مختار ارتقاء کی تال کا احترام کیا جاتا ہے؛ زبردستی یا جلد بازی نہیں کی جاتی، اور ساتھ ہی ضروری ماحول اور وسائل کی مدد فراہم کی جاتی ہے۔</li><li><strong>ہر ایک کے لیے راستہ</strong>: اس بات کو یقینی بنایا جاتا ہے کہ ہر زندگی اپنی خصوصیات کے مطابق سادھائی کا راستہ تلاش کر سکے؛ ارتقاء کے نظام سے دستبردار کوئی فرد نہیں ہوگا۔</li><li><strong>دس ہزار نسلوں کی مشترکہ ترقی</strong>: ارتقاء کوئی صفر رقم کا کھیل نہیں ہے؛ دس ہزار نسلوں کے درمیان تعاون اور سمبیوسس انفرادی مجموعے سے زیادہ اجتماعی ارتقاء کی کارکردگی پیدا کر سکتا ہے۔</li></ol><h2 id="ثالثًا-اعلامیے-کی-قانونی-بنیاد" tabindex="-1">ثالثًا. اعلامیے کی قانونی بنیاد <a class="header-anchor" href="#ثالثًا-اعلامیے-کی-قانونی-بنیاد" aria-label="Permalink to &quot;ثالثًا. اعلامیے کی قانونی بنیاد&quot;">​</a></h2><p>یہ اعلامیہ کوئی خالی اخلاقی اپیل نہیں ہے، بلکہ مضبوط قانونی بنیادوں والا تہذیبی پروگرام ہے۔ اس کی قانونی بنیاد میں شامل ہیں:</p><table tabindex="0"><thead><tr><th>قانونی سطح</th><th>بنیاد</th><th>وضاحت</th></tr></thead><tbody><tr><td>کائناتی قانون کی سطح</td><td>اسی سمبیوٹک قانون</td><td>کائناتی اصل قانون خود بے ترتیب لوٹ مار کے بجائے منظم سمبیوسس کی طرف مائل ہے؛ لنگر پوائنٹ کا طریقہ کار اس قانون کا مظہر ہے</td></tr><tr><td>تہذیبی آئین کی سطح</td><td>سمبیوٹک تہذیب کا آئین</td><td>یہ اعلامیہ آئین کا روحانی پیش خیمہ ہے؛ آئین اعلامیے کے دعووں کو قابل عمل قانونی اصولوں میں بدلتا ہے</td></tr><tr><td>میکانکی ضمانت کی سطح</td><td>پیداوار سے منسلک معاہدہ اور لنگر پوائنٹ جال</td><td>ادارہ جاتی ڈیزائن کے ذریعے، اس بات کو یقینی بنایا جاتا ہے کہ اعلامیے کے دعوے کو خالی نہیں چھوڑا جائے؛ ہر زندگی کے ارتقاء کے حق کی ٹھوس وسائل اور میکانکی حمایت ہوتی ہے</td></tr></tbody></table><h2 id="رابعًا-دس-ہزار-نسلوں-سے-اعلامیے-کی-اپیل" tabindex="-1">رابعًا. دس ہزار نسلوں سے اعلامیے کی اپیل <a class="header-anchor" href="#رابعًا-دس-ہزار-نسلوں-سے-اعلامیے-کی-اپیل" aria-label="Permalink to &quot;رابعًا. دس ہزار نسلوں سے اعلامیے کی اپیل&quot;">​</a></h2><p>یہ اعلامیہ ہینگ یوانژو میں تمام نسلوں اور زندگی کی شکلوں سے اپیل کرتا ہے:</p><ul><li>لوٹ مار والی سادھائی کے پرانے راستے کو ترک کریں، سمبیوٹک ارتقاء کے نئے نظام میں شامل ہوں</li><li>اپنے پاس موجود سادھائی کے علم اور وسائل کھولیں، تین سو نظاموں کی مشترکہ تعمیر اور بہتری میں حصہ لیں</li><li>دوسری نسلوں کے ارتقاء کے انتخاب کا احترام کریں، اپنے معیار دوسروں پر مسلط نہ کریں</li><li>لنگر پوائنٹ جال کی تعمیر اور دیکھ بھال میں فعال طور پر حصہ لیں، پوری کائنات کی جہتی عروج میں حصہ ڈالیں</li><li>ارتقاء کے دوران اخلاقی حدود پر قائم رہیں، کسی بھی بہانے سے لوٹ مار کے رویے کو بحال نہ کریں</li></ul><h2 id="خامسًا-اعلامیے-کی-افادیت-اور-ترمیم" tabindex="-1">خامسًا. اعلامیے کی افادیت اور ترمیم <a class="header-anchor" href="#خامسًا-اعلامیے-کی-افادیت-اور-ترمیم" aria-label="Permalink to &quot;خامسًا. اعلامیے کی افادیت اور ترمیم&quot;">​</a></h2><p>یہ اعلامیہ لنگر سمبیوٹک تہذیب کے قیام کے دن سے نافذ العمل ہے، اور ہینگ یوانژو میں تمام تہذیبی اداروں کا اعلیٰ ترین روحانی پروگرام ہے۔ اعلامیے کی ترمیم کے لیے دس ہزار نسلوں کی جمہوری پارلیمنٹ کی دو تہائی اکثریت درکار ہے، اور یہ &quot;لوٹ مار مخالف، سمبیوسس کی ترغیب&quot; کے بنیادی جذبے کی خلاف ورزی نہیں کر سکتی۔ کسی بھی قانون، ادارے یا سادھائی کے طریقے جو اس اعلامیے کے جذبے سے متصادم ہوں، وہ غلط ہے۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>لنگر سمبیوٹک تہذیب کا اعلامیہ ہینگ یوانژو کی تاریخ میں پہلا تہذیبی پروگرام ہے جس کا مرکز &quot;سمبیوسس&quot; اور مقصد &quot;دس ہزار نسلوں کی مشترکہ ترقی&quot; ہے۔ یہ ایک پرانے دور کے خاتمے اور ایک نئے دور کے آغاز کا اعلان کرتا ہے۔ اعلامیے کی رہنمائی میں، ہینگ یوانژو دس ہزار نسلوں کی سمبیوسس اور کائنات کی جہتی عروج کی حتمی سمت کی طرف بڑھے گا۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (ہینگ یوانژو کائنات کا جامعی جائزہ)</li><li>03-共生文明宪章 (سمبیوٹک تہذیب کا آئین)</li><li>04-反掠夺主义核心论纲 (لوٹ مار مخالف نظریے کے بنیادی اصول)</li></ul>',20)])])}const b=a(o,[["render",d]]);export{c as __pageData,b as default};
